"""Generate the offline procurement page and CSV from the audited JSON; no network."""
import csv
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
data = json.loads((ROOT / "beanlens-bom-v4.8.json").read_text())
rows = data["items"]
columns = [("id", "编号"), ("category", "分组"), ("name", "物料"), ("model", "型号/材料标准"),
           ("spec", "尺寸与电气规格"), ("qty", "数量"), ("unit", "单位"), ("selection", "方案"),
           ("readiness", "下单状态"), ("price_cny", "人民币单价"), ("price_basis", "价格依据"),
           ("check", "适配核对/用途"), ("old_ids", "对应旧BOM"), ("sources", "资料来源")]
with (ROOT / "beanlens-bom-v4.8.csv").open("w", encoding="utf-8-sig", newline="") as f:
    w = csv.writer(f, lineterminator="\n")
    w.writerow([c[1] for c in columns])
    for row in rows:
        w.writerow([" | ".join(row[k]) if isinstance(row[k], list) else row[k] for k, _ in columns])
def esc(value):
    return html.escape(str(value))
body = []
for r in rows:
    links = " · ".join(f'<a href="{esc(u)}" target="_blank" rel="noopener noreferrer">资料{i+1}</a>' for i, u in enumerate(r["sources"])) or "工程规格 / 用户输入"
    body.append(f'''<tr data-id="{esc(r['id'])}" data-category="{esc(r['category'])}" data-selection="{esc(r['selection'])}">
<td><b>{esc(r['id'])}</b><small>旧：{esc(', '.join(r['old_ids']) or '新增')}</small></td>
<td><b>{esc(r['name'])}</b><small>{esc(r['category'])} · {esc(r['selection'])}</small></td>
<td><b>{esc(r['model'])}</b><p>{esc(r['spec'])}</p>{links}</td><td>{r['qty']} {esc(r['unit'])}</td>
<td><span class="badge {'hold' if '暂缓' in r['readiness'] else ''}">{esc(r['readiness'])}</span><p>{esc(r['check'])}</p></td>
<td>{('¥'+format(r['price_cny'],'.2f')) if r['price_cny'] is not None else '待询价'}<small>{esc(r['price_basis'])}</small></td></tr>''')
mapping = []
for old in data["legacy_audit"]:
    mapping.append(f'<tr><td>{esc(old["id"])}</td><td>{esc(old["name"])}</td><td>{esc(old["action"])}</td><td>{esc(", ".join(old["new_ids"]))}</td></tr>')
